import { articleImage } from "./sportpaleis/catalog-images.ts";
import type { PilotBootstrap } from "./sportpaleis/pilot-api.ts";
import type { CatalogArticle, SportpaleisProductionElement, TeamkitProposal, TeamkitProposalItem, TeamkitProposalPlacement } from "./sportpaleis/workspace-data.ts";
import { buildTeamwearAssetLibrary, buildTeamwearCatalog, buildTeamwearRelationships, queryTeamwearCatalog, resolveTeamwearPrice, teamwearContextArticles, teamwearContextProductionAssets, teamwearProposalContextId, teamwearTeamorderHandoff, type TeamwearCatalogProduct } from "./sportpaleis-teamwear-foundations.ts";

function esc(value: unknown): string { return String(value ?? "").replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll('"', "&quot;").replaceAll("'", "&#039;"); }
function clientPlacementId(): string { return globalThis.crypto?.randomUUID?.() ?? `placement-${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`; }
function initial(value: string): string { return value.split(/\s+/u).filter(Boolean).slice(0, 2).map((part) => part[0]).join("").toLocaleUpperCase("nl-NL"); }
function articleFor(state: PilotBootstrap, item: TeamkitProposalItem): CatalogArticle | undefined { return state.articles.find(({ id }) => id === item.articleId) ?? state.articles.find(({ articleNumber }) => articleNumber === item.articleNumber) ?? state.articles.find(({ name }) => name === item.productName); }
function itemImage(state: PilotBootstrap, item: TeamkitProposalItem): string { return articleImage(item.catalogSnapshot?.imageKey ?? articleFor(state, item)?.imageKey); }
function euro(value: number | null | undefined): string { return typeof value === "number" ? new Intl.NumberFormat("nl-NL", { style: "currency", currency: "EUR" }).format(value) : "Prijs volgt"; }
function associationFor(state: PilotBootstrap, proposal: TeamkitProposal) { return state.associations.find(({ id }) => id === proposal.association.id) ?? state.associations.find(({ name }) => name === proposal.association.name); }
function clubArticles(state: PilotBootstrap, proposal: TeamkitProposal): CatalogArticle[] { return teamwearContextArticles(state, proposal); }
function clubAssets(state: PilotBootstrap, proposal: TeamkitProposal): SportpaleisProductionElement[] { return teamwearContextProductionAssets(state, proposal); }
function productGroup(category: string, name: string): "WEDSTRIJD" | "TRAINING" | "PRESENTATIE" | "ACCESSOIRES" {
  const value = `${category} ${name}`.toLocaleLowerCase("nl-NL");
  if (/tas|rugzak|sok|bal|access/iu.test(value)) return "ACCESSOIRES";
  if (/train|zip|hood|sweat/iu.test(value)) return "TRAINING";
  if (/polo|jas|present|regen|winter/iu.test(value)) return "PRESENTATIE";
  return "WEDSTRIJD";
}
function itemGroup(item: TeamkitProposalItem, state: PilotBootstrap): string { const article = articleFor(state, item); return productGroup(article?.category ?? "", item.productName); }
function sourceUrl(base: string, proposalId: string, sourceId: string): string { return `${base.replace(/\/workspace\/sportpaleis$/u, "")}/api/sportpaleis/v1/teamkit-proposals/${encodeURIComponent(proposalId)}/sources/${encodeURIComponent(sourceId)}`; }
function associationLogo(state: PilotBootstrap, proposal: TeamkitProposal): string | null { const logo = associationFor(state, proposal)?.workspaceLogo; return logo ? `data:${logo.mimeType};base64,${logo.dataBase64}` : null; }
function assetPreview(state: PilotBootstrap, proposal: TeamkitProposal, asset: SportpaleisProductionElement): string {
  const logo = associationLogo(state, proposal);
  const hasTransparentVectorPreview = Boolean(asset.controlledVector || asset.sourceLayers?.vectorSource || asset.sourceLayers?.visualSource?.mimeType === "image/svg+xml");
  if (hasTransparentVectorPreview) return `<img src="/api/sportpaleis/v1/production-assets/${encodeURIComponent(asset.id)}/preview.svg" alt="${esc(asset.name)}">`;
  return logo && asset.ownerType === "ASSOCIATION" ? `<img src="${logo}" alt="">` : `<span class="sp-teamkit-asset-monogram">${esc(initial(asset.name))}</span>`;
}
function proposalSourcePreview(proposal: TeamkitProposal, sourceId: string | null, base: string): string | null {
  if (!sourceId) return null; const source = proposal.sources.find(({ id }) => id === sourceId); if (!source || !["SVG", "PNG", "JPG", "WEBP"].includes(source.format)) return null;
  return sourceUrl(base, proposal.id, source.id);
}
function statusLabel(status: string): string { return ({ DRAFT: "Concept", WAITING_FOR_CUSTOMER_INPUT: "Wacht op club", READY_FOR_DESIGN: "Klaar voor Studio", IN_DESIGN: "In Studio", READY_FOR_REVIEW: "Klaar voor controle", SENT_TO_CUSTOMER: "Bij de club", CUSTOMER_FEEDBACK: "Feedback ontvangen", READY_FOR_APPROVAL: "Klaar voor akkoord", APPROVED: "Akkoord", ARCHIVED: "Gearchiveerd" } as Record<string, string>)[status] ?? status; }

function visualProductCard(article: CatalogArticle, proposal: TeamkitProposal, selected: boolean): string {
  const group = productGroup(article.category, article.name);
  return `<article class="sp-club-product-card"><div class="sp-club-product-card__visual"><img src="${articleImage(article.imageKey)}" alt="${esc(article.name)}"></div><div><p>${esc(group.toLowerCase())}</p><h3>${esc(article.name)}</h3><span>Bestaande clubvariant</span></div><form data-add-teamkit-collection-item data-proposal-id="${esc(proposal.id)}" data-article-id="${esc(article.id)}"><button class="sp-button ${selected ? "sp-button--secondary" : "sp-button--primary"}" ${selected ? "disabled" : ""}>${selected ? "In collectie" : "Voeg toe"}</button></form></article>`;
}

function catalogProductCard(product: TeamwearCatalogProduct, proposal: TeamkitProposal, associationName: string | null, selectedIds: Set<string>): string {
  const association = associationName?.toLocaleLowerCase("nl-NL");
  const variant = product.variants.find(({ associationNames }) => associationNames.some((name) => name.toLocaleLowerCase("nl-NL") === association)) ?? product.variants[0];
  const quote = resolveTeamwearPrice(product, 10, teamwearProposalContextId(proposal)); const selected = selectedIds.has(variant.sourceArticleId || product.id); const group = product.use; const audience = product.audiences.join(" ");
  const snapshot = { catalogProductId: product.id, brand: product.brand, supplierName: product.supplierName, supplierArticleName: product.supplierArticleName, supplierArticleNumber: product.supplierArticleNumber, category: product.category, collection: product.collection, audience: product.audiences, colorLabel: variant.colorLabel, imageKey: variant.imageKey, advicePriceEur: quote.advicePriceEur, effectivePriceEur: quote.effectivePriceEur, priceLabel: quote.label, minimumQuantity: quote.minimumQuantity, pricingPolicyRef: quote.policyRef, sourceAdapterId: product.sourceAdapterId, sourceStatus: product.sourceStatus };
  return `<article class="sp-club-product-card sp-catalog-product-card" data-catalog-product data-catalog-brand="${esc(product.brand)}" data-catalog-group="${group}" data-catalog-audience="${esc(audience)}" data-catalog-search-value="${esc(`${product.brand} ${product.model} ${product.supplierArticleNumber} ${group} ${audience}`.toLocaleLowerCase("nl-NL"))}"><div class="sp-club-product-card__visual"><img loading="lazy" src="${articleImage(variant.imageKey)}" alt="${esc(product.model)}"><span>${esc(product.brand)}</span><em>${product.sourceStatus === "CONTROLLED_FIXTURE" ? "Reviewdata" : "Catalogus"}</em></div><div><p>${esc(group.toLowerCase())}</p><h3>${esc(product.model)}</h3><span>${esc(product.supplierArticleNumber)} · ${esc(product.audiences.map((value) => ({ JUNIOR: "Junior", SENIOR: "Senior", MEN: "Heren", WOMEN: "Dames", UNISEX: "Unisex" } as Record<string, string>)[value]).join(" · "))}</span><div class="sp-catalog-color"><i style="--swatch:${esc(variant.colorHex ?? "#102448")}" aria-hidden="true"></i>${esc(variant.colorLabel)}</div><div class="sp-catalog-price"><small>Adviesprijs ${euro(quote.advicePriceEur)}</small>${quote.effectivePriceEur != null ? `<strong>${esc(quote.label)} ${euro(quote.effectivePriceEur)}</strong>${quote.minimumQuantity ? `<span>vanaf ${quote.minimumQuantity} stuks</span>` : ""}` : ""}</div></div><details class="sp-catalog-product-detail"><summary>Bekijk product & maten</summary><strong>Beschikbare maten</strong><p>${variant.availableSizes.length ? esc(variant.availableSizes.join(" · ")) : "Maten nog te bevestigen"}</p><small>Aantallen en personen volgen pas in Teamorder.</small></details><form data-add-teamkit-collection-item data-proposal-id="${esc(proposal.id)}" data-article-id="${esc(variant.sourceArticleId)}" data-catalog-snapshot="${esc(JSON.stringify(snapshot))}" data-catalog-product-name="${esc(product.model)}"><button class="sp-button ${selected ? "sp-button--secondary" : "sp-button--primary"}" ${selected ? "disabled" : ""}>${selected ? "In collectie" : "Voeg aan collectie toe"}</button></form></article>`;
}

function clubAssetCard(state: PilotBootstrap, proposal: TeamkitProposal, asset: SportpaleisProductionElement): string {
  return `<button type="button" class="sp-club-asset-card" data-action="studio-add-asset" data-asset-id="${esc(asset.id)}" data-asset-version="${esc(asset.version ?? "")}" data-asset-label="${esc(asset.name)}" data-asset-kind="${asset.applications?.some(({ kind }) => kind === "SPONSOR") ? "SPONSOR" : "CLUB_LOGO"}" data-asset-recolorable="${Boolean(asset.controlledVector)}">${assetPreview(state, proposal, asset)}<span><strong>${esc(asset.name)}</strong><small>${asset.applications?.[0]?.kind === "SPONSOR" ? "Sponsor" : "Productieasset"}</small></span></button>`;
}

function sourceAssetCard(originProposal: TeamkitProposal, source: TeamkitProposal["sources"][number], base: string, sourceReference = source.id): string {
  const preview = ["SVG", "PNG", "JPG", "WEBP"].includes(source.format) ? `<img src="${sourceUrl(base, originProposal.id, source.id)}" alt="">` : `<span class="sp-teamkit-asset-monogram">${esc(source.format)}</span>`;
  return `<button type="button" class="sp-club-asset-card" data-action="studio-add-source" data-source-id="${esc(sourceReference)}" data-asset-label="${esc(source.filename.replace(/\.[^.]+$/u, ""))}" data-asset-kind="SPONSOR" data-asset-quality="${esc(source.quality.status)}" data-asset-recolorable="${source.quality.status === "VECTOR_SUITABLE"}">${preview}<span><strong>${esc(source.filename)}</strong><small>${source.quality.status === "VECTOR_SUITABLE" ? "Vector · kleurvariant mogelijk" : "Visueel bruikbaar · controle nodig"}</small></span></button>`;
}

function associationLogoAssetCard(state: PilotBootstrap, proposal: TeamkitProposal): string {
  const association = associationFor(state, proposal); const logo = associationLogo(state, proposal); if (!association?.workspaceLogo || !logo) return "";
  const sourceReference = `association-logo:${association.id}:${association.workspaceLogo.sha256}`;
  const visualQuality = association.workspaceLogo.mimeType === "image/png" ? "PNG · transparantie controleren" : "Betere/transparante bron aanbevolen";
  return `<button type="button" class="sp-club-asset-card" data-action="studio-add-source" data-source-id="${esc(sourceReference)}" data-asset-label="Clublogo" data-asset-kind="CLUB_LOGO" data-asset-quality="${association.workspaceLogo.mimeType === "image/png" ? "RASTER_HIGH_RES_REVIEW" : "LOW_RES_BETTER_SOURCE_REQUIRED"}"><img src="${logo}" alt=""><span><strong>Clublogo</strong><small>${visualQuality}</small></span></button>`;
}

function clubHome(state: PilotBootstrap, proposal: TeamkitProposal, base: string): string {
  const association = associationFor(state, proposal); const articles = clubArticles(state, proposal); const assets = clubAssets(state, proposal); const logo = associationLogo(state, proposal); const catalog = queryTeamwearCatalog(buildTeamwearCatalog(state), { limit: 12 });
  const collectionIds = new Set(proposal.items.map(({ articleId }) => articleId).filter((id): id is string => Boolean(id)));
  const counts = ["WEDSTRIJD", "TRAINING", "PRESENTATIE", "ACCESSOIRES"].map((group) => ({ group, count: articles.filter((article) => productGroup(article.category, article.name) === group).length }));
  const library = `${associationLogoAssetCard(state, proposal)}${assets.map((asset) => clubAssetCard(state, proposal, asset)).join("")}${proposal.sources.map((source) => sourceAssetCard(proposal, source, base)).join("")}`;
  return `<section class="sp-club-experience" id="club-experience"><header class="sp-club-hero"><div class="sp-club-hero__identity">${logo ? `<img src="${logo}" alt="Logo ${esc(association?.name)}">` : `<span>${esc(initial(association?.name ?? proposal.customer.name))}</span>`}<div><p>BESTAANDE CONTEXT</p><h1>${esc(association?.name ?? proposal.customer.name)}</h1><strong>${esc(proposal.team ?? "Teamwear-collectie")} · ${esc(proposal.season ?? "Nieuw seizoen")}</strong></div></div><div class="sp-club-hero__actions"><span>${esc(statusLabel(proposal.status))} · V${proposal.currentRevision}</span><a class="sp-button sp-button--primary" href="#teamkit-studio">Open Teamwear Studio</a><a class="sp-button sp-button--secondary" data-link href="${base}/voorstellen/${encodeURIComponent(proposal.id)}?mode=beheer">Details & afhandeling</a></div></header><nav class="sp-club-subnav" aria-label="Teamwear"><a href="#huidige-collectie">Bekende kleding</a><a href="#catalogus">Catalogus</a><a href="#onze-collectie">Collectie</a><a href="#teamkit-studio">Studio</a><a href="#klantpreview">Voorstel</a></nav><section class="sp-club-overview"><article><p>HUIDIGE COLLECTIE</p><strong>${articles.length}</strong><span>bekende artikelen uit dezelfde context</span></article>${counts.map(({ group, count }) => `<article><p>${group}</p><strong>${count}</strong><span>${count === 1 ? "artikel" : "artikelen"}</span></article>`).join("")}<article><p>ASSETS</p><strong>${assets.length + proposal.sources.length + (logo ? 1 : 0)}</strong><span>toegestane assets voor deze context</span></article></section><section class="sp-club-section" id="huidige-collectie"><div class="sp-club-section__head"><div><p>HERGEBRUIK</p><h2>Bekende kleding & tassen</h2><span>Rechtstreeks uit bestaande artikelcontext; geen tweede Teamwear-productwaarheid.</span></div></div><div class="sp-club-product-strip">${articles.slice(0, 10).map((article) => visualProductCard(article, proposal, collectionIds.has(article.id))).join("") || `<p class="sp-muted">Nog geen betrouwbare kledingcontext; start vanuit de catalogus.</p>`}</div></section><section class="sp-club-section sp-club-library"><div class="sp-club-section__head"><div><p>CONTEXTASSETS</p><h2>Logo’s en beelden die hier al horen</h2><span>De interne masterbibliotheek blijft afgeschermd; hier staat alleen wat aan deze context is gekoppeld.</span></div></div><div class="sp-club-assets">${library || `<p class="sp-muted">Nog geen assets beschikbaar.</p>`}</div></section><section class="sp-club-section sp-teamwear-catalog" id="catalogus"><div class="sp-club-section__head"><div><p>SPORTPALEIS PRODUCT CATALOG</p><h2>Ontdek complete Teamwear</h2><span>Model, kleur en doelgroep centraal; maat-SKU’s verschijnen niet als losse producten.</span></div><a class="sp-fixture-note" href="https://www.stanno.com/nl/service/catalogus" target="_blank" rel="noreferrer">Officiële Stanno-reference · reviewfixtures actief</a></div><div class="sp-catalog-discovery"><label><span>Zoek op merk, model of artikelnummer</span><input type="search" data-teamkit-catalog-search placeholder="Bijv. BV6708 of trainingsjack"></label><div class="sp-catalog-filters" role="group" aria-label="Catalogusfilter"><button class="is-active" type="button" data-action="catalog-filter" data-filter="ALL">Alles</button><button type="button" data-action="catalog-filter" data-filter="WEDSTRIJD">Wedstrijd</button><button type="button" data-action="catalog-filter" data-filter="TRAINING">Training</button><button type="button" data-action="catalog-filter" data-filter="PRESENTATIE">Presentatie</button><button type="button" data-action="catalog-filter" data-filter="ACCESSOIRES">Accessoires</button><button type="button" data-action="catalog-filter" data-filter="AUDIENCE:JUNIOR">Junior</button><button type="button" data-action="catalog-filter" data-filter="AUDIENCE:MEN">Heren</button><button type="button" data-action="catalog-filter" data-filter="AUDIENCE:WOMEN">Dames</button><button type="button" data-action="catalog-filter" data-filter="AUDIENCE:UNISEX">Unisex</button></div></div><div class="sp-catalog-result-note"><strong>${catalog.total} modellen</strong><span>12 resultaten · begrensd/paginable voor 5.000+</span></div><div class="sp-club-product-grid">${catalog.products.map((product) => catalogProductCard(product, proposal, proposal.association.name, collectionIds)).join("")}</div></section><section class="sp-club-section" id="onze-collectie"><div class="sp-club-section__head"><div><p>COLLECTIE ${esc(proposal.season ?? "NIEUW")}</p><h2>Onze collectie</h2><span>Wedstrijd, training, presentatie en accessoires als één samenhangende set.</span></div><a class="sp-button sp-button--primary" href="#teamkit-studio">Open in Teamwear Studio</a></div>${collectionBoard(state, proposal)}</section></section>`;
}

function collectionBoard(state: PilotBootstrap, proposal: TeamkitProposal): string {
  const groups = ["WEDSTRIJD", "TRAINING", "PRESENTATIE", "ACCESSOIRES"] as const;
  return `<div class="sp-collection-board">${groups.map((group) => { const items = proposal.items.filter((item) => itemGroup(item, state) === group); return `<section><header><span>${group}</span><strong>${items.length}</strong></header><div>${items.map((item) => { const article = articleFor(state, item); return `<button type="button" data-action="studio-select-item" data-item-id="${esc(item.id)}" class="sp-collection-piece"><img src="${articleImage(article?.imageKey)}" alt=""><span><strong>${esc(item.productName)}</strong><small>${esc(item.color)}</small></span></button>`; }).join("") || `<p>Kies een artikel uit de catalogus</p>`}</div></section>`; }).join("")}</div>`;
}

const DEFAULT_POSITION: Record<string, [number, number]> = { LINKERBORST: [35, 27], RECHTERBORST: [65, 27], MIDDENBORST: [50, 42], RUG_BOVEN: [50, 26], RUG_MIDDEN: [50, 48], MOUW_LINKS: [18, 36], MOUW_RECHTS: [82, 36], SHORT_LINKS: [38, 64], SHORT_RECHTS: [62, 64], BROEK: [50, 60], TAS: [50, 50] };
function visualPoint(placement: TeamkitProposalPlacement): [number, number] { return placement.visualPosition?.coordinateSpace === "GARMENT_PRINT_AREA_V1" ? [placement.visualPosition.xPercent, placement.visualPosition.yPercent] : DEFAULT_POSITION[placement.preset] ?? [50, 50]; }
type VisualGarmentSurface = "FRONT_TORSO" | "BACK_TORSO" | "LEFT_SLEEVE" | "RIGHT_SLEEVE" | "LOWER_GARMENT" | "ACCESSORY";
const SURFACE_BOUNDS: Record<VisualGarmentSurface, { minX: number; maxX: number; minY: number; maxY: number; maxWidth: number }> = {
  FRONT_TORSO: { minX: 24, maxX: 76, minY: 14, maxY: 86, maxWidth: 58 },
  BACK_TORSO: { minX: 24, maxX: 76, minY: 14, maxY: 86, maxWidth: 58 },
  LEFT_SLEEVE: { minX: 7, maxX: 25, minY: 20, maxY: 43, maxWidth: 16 },
  RIGHT_SLEEVE: { minX: 75, maxX: 93, minY: 20, maxY: 43, maxWidth: 16 },
  LOWER_GARMENT: { minX: 24, maxX: 76, minY: 48, maxY: 90, maxWidth: 42 },
  ACCESSORY: { minX: 14, maxX: 86, minY: 14, maxY: 86, maxWidth: 64 },
};
function visualSurfaceForPreset(preset: string): VisualGarmentSurface {
  if (preset === "MOUW_LINKS") return "LEFT_SLEEVE";
  if (preset === "MOUW_RECHTS") return "RIGHT_SLEEVE";
  if (["RUG_BOVEN", "RUG_MIDDEN"].includes(preset)) return "BACK_TORSO";
  if (["SHORT_LINKS", "SHORT_RECHTS", "BROEK"].includes(preset)) return "LOWER_GARMENT";
  if (preset === "TAS") return "ACCESSORY";
  return "FRONT_TORSO";
}
function constrainPlacementToSurface(placement: HTMLElement, x: number, y: number, requestedWidth = Number(hiddenValue(placement, "placementWidth").value)): { x: number; y: number; width: number } {
  const surface = (placement.dataset.visualSurface ?? "FRONT_TORSO") as VisualGarmentSurface; const bounds = SURFACE_BOUNDS[surface]; const width = Math.max(5, Math.min(bounds.maxWidth, requestedWidth));
  const half = width / 2; return { x: Math.max(bounds.minX + half, Math.min(bounds.maxX - half, x)), y: Math.max(bounds.minY, Math.min(bounds.maxY, y)), width };
}
function applyVisualSurface(placement: HTMLElement, preset: string): void {
  placement.dataset.visualSurface = visualSurfaceForPreset(preset); const current = constrainPlacementToSurface(placement, Number(hiddenValue(placement, "placementVisualX").value), Number(hiddenValue(placement, "placementVisualY").value));
  hiddenValue(placement, "placementWidth").value = current.width.toFixed(1); placement.style.setProperty("--placement-width", `${current.width}%`);
}
function placementMarkup(state: PilotBootstrap, proposal: TeamkitProposal, placement: TeamkitProposalPlacement, base: string): string {
  const [x, y] = visualPoint(placement); const asset = placement.productionAssetId ? state.productionElements.find(({ id }) => id === placement.productionAssetId) : undefined; const sourcePreview = proposalSourcePreview(proposal, placement.sourceId, base); const logo = associationLogo(state, proposal);
  const image = sourcePreview ?? (asset?.ownerType === "ASSOCIATION" ? logo : null); const display = image ? `<img src="${image}" alt="${esc(placement.label)}" draggable="false">` : `<span>${esc(placement.text ?? (asset ? initial(asset.name) : placement.label))}</span>`;
  const source = proposal.sources.find(({ id }) => id === placement.sourceId); const recolorable = !image || Boolean(asset?.controlledVector) || source?.quality.status === "VECTOR_SUITABLE";
  const visualQuality = source?.quality.status ?? (placement.productionAssetId ? "PRODUCTION_READY" : "TEXT");
  return `<article class="sp-studio-placement sp-studio-placement--${placement.kind.toLocaleLowerCase()}" data-proposal-placement data-placement-id="${esc(placement.id)}" data-placement-side="${placement.side}" data-recolorable="${recolorable}" data-visual-quality="${esc(visualQuality)}" data-color-override="${esc(placement.colorOverride ?? "")}" style="--placement-x:${x}%;--placement-y:${y}%;--placement-width:${placement.widthPercent}%;--placement-color:${esc(placement.colorOverride ?? "#ffffff")}"><input type="hidden" name="placementKind" value="${placement.kind}"><input type="hidden" name="placementLabel" value="${esc(placement.label)}"><input type="hidden" name="placementSide" value="${placement.side}"><input type="hidden" name="placementPreset" value="${placement.preset}"><input type="hidden" name="placementText" value="${esc(placement.text ?? "")}"><input type="hidden" name="placementColor" value="${esc(placement.colorOverride ?? "")}"><input type="hidden" name="placementWidth" value="${placement.widthPercent}"><input type="hidden" name="placementVisualX" value="${x}"><input type="hidden" name="placementVisualY" value="${y}"><input type="hidden" name="placementSourceId" value="${esc(placement.sourceId ?? "")}"><input type="hidden" name="placementAssetId" value="${esc(placement.productionAssetId ?? "")}"><input type="hidden" name="placementRoute" value="${placement.route}"><input type="hidden" name="placementSupplier" value="${esc(placement.supplierName ?? "")}"><input type="hidden" name="placementNote" value="${esc(placement.note ?? "")}"><input type="hidden" name="placementPhysicalWidthMm" value="${placement.physicalSizeOverride?.widthMm ?? ""}"><input type="hidden" name="placementPhysicalHeightMm" value="${placement.physicalSizeOverride?.heightMm ?? ""}"><button type="button" class="sp-studio-placement__body" aria-label="${esc(placement.label)} selecteren">${display}</button><button type="button" class="sp-studio-resize" data-studio-resize aria-label="${esc(placement.label)} schalen"></button></article>`;
}
function hiddenItemFields(item: TeamkitProposalItem): string { return `<input type="hidden" name="productName" value="${esc(item.productName)}"><input type="hidden" name="articleNumber" value="${esc(item.articleNumber ?? "")}"><input type="hidden" name="itemColor" value="${esc(item.color)}"><input type="hidden" name="itemQuantity" value="${item.quantity ?? ""}"><input type="hidden" name="itemSizes" value="${esc(item.sizes.join(", "))}"><input type="hidden" name="itemTeam" value="${esc(item.team ?? "")}"><input type="hidden" name="itemNotes" value="${esc(item.notes ?? "")}"><input type="hidden" name="catalogSnapshot" value="${esc(item.catalogSnapshot ? JSON.stringify(item.catalogSnapshot) : "")}">`; }
function itemStage(state: PilotBootstrap, proposal: TeamkitProposal, item: TeamkitProposalItem, base: string, active: boolean): string {
  const front = item.placements.filter(({ side }) => side === "FRONT").map((placement) => placementMarkup(state, proposal, placement, base)).join(""); const back = item.placements.filter(({ side }) => side === "BACK").map((placement) => placementMarkup(state, proposal, placement, base)).join("");
  const image = itemImage(state, item); const view = (side: "FRONT" | "BACK", placements: string) => `<div class="sp-studio-view" data-studio-view="${side}" ${side === "BACK" ? "hidden" : ""}><div class="sp-studio-garment ${side === "BACK" ? "is-back" : ""}"><img src="${image}" alt="${esc(item.productName)} ${side === "FRONT" ? "voorzijde" : "achterzijde visualisatie"}" draggable="false"><div class="sp-studio-print-area" data-print-area="${side}" aria-label="${side === "FRONT" ? "Voorzijde" : "Achterzijde"} bedrukvlak">${placements}</div></div><p>${side === "FRONT" ? "Voorzijde" : "Achterzijde"} · conceptplaatsing binnen veilig garment-vlak</p></div>`;
  return `<section class="sp-studio-item" data-proposal-item data-item-id="${esc(item.id)}" data-article-id="${esc(item.articleId ?? "")}" ${active ? "" : "hidden"}>${hiddenItemFields(item)}<header class="sp-studio-itembar"><div><img src="${image}" alt=""><span><strong>${esc(item.productName)}</strong><small>${esc(item.color)} · maten en aantallen volgen in Teamorder</small></span></div><div class="sp-studio-side-switch" role="group" aria-label="Kledingzijde"><button class="is-active" type="button" data-action="studio-side" data-side="FRONT">Voorzijde</button><button type="button" data-action="studio-side" data-side="BACK">Achterzijde</button></div></header><div class="sp-studio-canvas">${view("FRONT", front)}${view("BACK", back)}</div></section>`;
}

function studio(state: PilotBootstrap, proposal: TeamkitProposal, base: string): string {
  const editable = proposal.status !== "APPROVED"; const allAssets = state.productionElements.filter(({ lifecycleStatus }) => lifecycleStatus === "PRODUCTION_READY"); const libraryProjection = buildTeamwearAssetLibrary(state, proposal);
  const sharedSourceCards = libraryProjection.filter(({ previewKind, sourceProposalId, sourceId }) => previewKind === "PROPOSAL_SOURCE" && sourceProposalId && sourceId).map((entry) => { const origin = state.teamkitProposals?.find(({ id }) => id === entry.sourceProposalId); const source = origin?.sources.find(({ id }) => id === entry.sourceId); return origin && source ? sourceAssetCard(origin, source, base, origin.id === proposal.id ? source.id : entry.id) : ""; }).join("");
  const library = `${associationLogoAssetCard(state, proposal)}${allAssets.map((asset) => clubAssetCard(state, proposal, asset)).join("")}${sharedSourceCards}`;
  const catalog = queryTeamwearCatalog(buildTeamwearCatalog(state), { limit: 8 }); const selectedIds = new Set(proposal.items.map(({ articleId, catalogSnapshot }) => articleId || catalogSnapshot?.catalogProductId).filter((id): id is string => Boolean(id)));
  const handoff = teamwearTeamorderHandoff(proposal); const quoteRows = proposal.items.map((item) => { const snapshot = item.catalogSnapshot; const article = articleFor(state, item); const advice = snapshot?.advicePriceEur ?? article?.priceConfiguration?.articleUnitPriceEur ?? null; const effective = snapshot?.effectivePriceEur ?? advice; return `<article><img src="${itemImage(state, item)}" alt=""><span><strong>${esc(item.productName)}</strong><small>${esc(item.articleNumber ?? "Artikel volgt")} · ${esc(item.color)}</small><em>${advice != null ? `Adviesprijs ${euro(advice)}` : "Prijs controleren"}</em></span><b>${effective != null ? euro(effective) : "–"}</b></article>`; }).join("");
  const total = proposal.items.reduce((sum, item) => sum + Number(item.catalogSnapshot?.effectivePriceEur ?? articleFor(state, item)?.priceConfiguration?.articleUnitPriceEur ?? 0) * Number(item.catalogSnapshot?.minimumQuantity ?? 10), 0);
  return `<section class="sp-teamwear-studio-wrap" id="teamkit-studio"><header class="sp-teamwear-studio-head"><div><p>TEAMWEAR STUDIO</p><h2>${esc(proposal.items[0]?.productName ?? "Visueel ontwerpen")}</h2><span>${esc(proposal.customer.name)}${proposal.team ? ` · ${esc(proposal.team)}` : ""}</span></div><div class="sp-studio-head-actions"><span class="sp-studio-save-state" data-studio-save-state>${editable ? "Alles opgeslagen" : "Approved versie · alleen lezen"}</span><button type="button" data-action="studio-undo" title="Ongedaan maken">↶</button><button type="button" data-action="studio-redo" title="Opnieuw">↷</button><a class="sp-button sp-button--secondary" href="#klantpreview">Voorstel bekijken</a></div></header>${proposal.items.length ? `<div class="sp-teamwear-studio" data-teamkit-studio data-proposal-id="${esc(proposal.id)}" data-editable="${editable}"><aside class="sp-teamwear-discovery"><div class="sp-studio-panel-title"><strong>Catalogus</strong><small>${catalog.total} modellen · 8 geladen</small></div><label class="sp-studio-search"><input type="search" data-teamkit-catalog-search placeholder="Merk, model, artikelnummer"></label><div class="sp-studio-catalog-filters"><button class="is-active" type="button" data-action="catalog-filter" data-filter="ALL">Alles</button><button type="button" data-action="catalog-filter" data-filter="WEDSTRIJD">Wedstrijd</button><button type="button" data-action="catalog-filter" data-filter="TRAINING">Training</button><button type="button" data-action="catalog-filter" data-filter="PRESENTATIE">Presentatie</button></div><div class="sp-studio-catalog">${catalog.products.map((product) => catalogProductCard(product, proposal, proposal.association.name, selectedIds)).join("")}</div><div class="sp-studio-panel-title"><strong>Asset Library <i>intern</i></strong><small>${libraryProjection.length} masters · klant ziet alleen gekoppelde assets</small></div><div class="sp-studio-tabs"><button class="is-active" type="button">Context</button><button type="button">Sponsors</button><button type="button">Logo’s</button><button type="button">Beelden</button></div><div class="sp-studio-asset-list">${library || `<p class="sp-muted">Nog geen assets.</p>`}</div>${editable ? `<div class="sp-studio-add"><span>Tekst & nummers</span><button type="button" data-action="studio-add-text" data-kind="INITIALS" data-text="SP">+ Initialen</button><button type="button" data-action="studio-add-text" data-kind="BACK_NUMBER" data-text="10">+ Rugnummer</button><button type="button" data-action="studio-add-text" data-kind="FREE_TEXT" data-text="BRANDWEER ALMERE">+ Vrije opdruk</button></div><form data-teamkit-source-form data-proposal-id="${esc(proposal.id)}" class="sp-studio-upload"><label>+ Logo, sponsor of beeld<input name="sources" type="file" accept=".svg,.eps,.ai,.pdf,.png,.jpg,.jpeg" required></label><button>Uploaden</button></form>` : ""}</aside><form class="sp-studio-workspace" data-teamkit-editor-form data-proposal-id="${esc(proposal.id)}" data-proposal-revision="${proposal.aggregateRevision}"><main><div class="sp-studio-toolbar" role="toolbar" aria-label="Teamwear gereedschappen"><button type="button" class="is-active" title="Selecteren">↖</button><button type="button" data-action="studio-align-x" title="Horizontaal centreren">↔</button><button type="button" data-action="studio-align-y" title="Verticaal centreren">↕</button><button type="button" data-action="studio-layer-front" title="Naar voren">↑</button><button type="button" data-action="studio-layer-back" title="Naar achter">↓</button><button type="button" data-action="studio-duplicate" title="Dupliceren">⧉</button><button type="button" data-action="studio-reset" title="Veilige positie herstellen">⌂</button><button type="button" data-action="studio-remove-placement" title="Verwijderen">⌫</button></div><nav class="sp-studio-itemrail" aria-label="Collectie in Studio">${proposal.items.map((item, index) => `<button type="button" class="${index === 0 ? "is-active" : ""}" data-action="studio-select-item" data-item-id="${esc(item.id)}"><img src="${itemImage(state, item)}" alt=""><span>${esc(item.productName)}</span></button>`).join("")}</nav>${proposal.items.map((item, index) => itemStage(state, proposal, item, base, index === 0)).join("")}</main><aside class="sp-studio-properties" data-studio-properties><div class="sp-studio-properties__empty"><span>↖</span><strong>Selecteer een element</strong><p>Sleep direct op de kleding. Hulplijnen en veilige zones helpen je precies plaatsen.</p></div><div class="sp-studio-properties__selected" hidden><header><div><p>GESELECTEERD</p><h3 data-property-title>Bedrukking</h3></div><button type="button" data-action="studio-remove-placement" aria-label="Verwijderen">×</button></header><label>Naam<input data-property="label" maxlength="120"></label><label data-text-property>Tekst / nummer<input data-property="text" maxlength="120"></label><div class="sp-studio-color" data-color-property><strong>Kleurvariant</strong><div><button type="button" data-action="studio-color" data-color="#ffffff" aria-label="Wit"></button><button type="button" data-action="studio-color" data-color="#101419" aria-label="Zwart"></button><button type="button" data-action="studio-color" data-color="#d3172f" aria-label="Rood"></button><input data-property="color" type="color" value="#ffffff" aria-label="Eigen kleur"></div><small>Non-destructief; originele bron blijft intact.</small></div><label>Positiezone<select data-property="preset"><option value="LINKERBORST">Linkerborst</option><option value="RECHTERBORST">Rechterborst</option><option value="MIDDENBORST">Middenvoor</option><option value="RUG_BOVEN">Rug boven</option><option value="RUG_MIDDEN">Middenachter</option><option value="MOUW_LINKS">Mouw links</option><option value="MOUW_RECHTS">Mouw rechts</option><option value="SHORT_LINKS">Short links</option><option value="SHORT_RECHTS">Short rechts</option></select></label><label>Visuele grootte<input data-property="width" type="range" min="5" max="70" step="1"><output data-property-output="width"></output></label><div class="sp-studio-quick-align"><button type="button" data-action="studio-align-x">Centreer ↔</button><button type="button" data-action="studio-align-y">Centreer ↕</button><button type="button" data-action="studio-reset">Reset</button></div><div class="sp-studio-production-size"><strong>Productie-informatie</strong><p data-production-size-copy>Bestaand productieprofiel/asset blijft leidend.</p><div><label>Breedte mm<input data-property="physicalWidth" type="number" min="1" max="1000" step="0.1" placeholder="Volgens profiel"></label><label>Hoogte mm<input data-property="physicalHeight" type="number" min="1" max="1000" step="0.1" placeholder="Volgens profiel"></label></div><small>Canvaspositie is geen productie-mm. Alleen een expliciete gecontroleerde override wordt production-authoritative.</small></div><label>Wie bedrukt dit?<select data-property="route"><option value="INTERN_BEDRUKKEN">Wijzelf</option><option value="EXTERNE_BEDRUKKER">Externe bedrukker</option><option value="NOG_TE_BEPALEN">Later bepalen</option></select></label></div><footer><label>Revision-notitie<input name="revisionReason" value="${proposal.status === "CUSTOMER_FEEDBACK" ? "Klantfeedback verwerkt" : "Teamwear-opmaak bijgewerkt"}" required></label><button class="sp-button sp-button--primary" ${editable ? "" : "disabled"}>Revision opslaan</button></footer></aside></form><aside class="sp-teamwear-quote"><header><p>VOORSTELOVERZICHT</p><h3>${esc(proposal.proposalNumber)} · V${proposal.currentRevision}</h3><span>${esc(proposal.customer.name)}</span></header><div class="sp-teamwear-quote-items">${quoteRows}</div><section><span>Prijsindicatie (10 stuks)</span><strong>${total ? euro(total) : "Prijzen controleren"}</strong><small>Adviesprijs en Teamprijs/Jullie prijs. Geen interne marge zichtbaar.</small></section><a class="sp-button sp-button--primary" data-link href="${base}/orders/team?fromTeamwear=${encodeURIComponent(handoff.proposalId)}">Naar maten & aantallen →</a><button class="sp-button sp-button--secondary" type="button" data-action="teamwear-ready" data-proposal-id="${esc(proposal.id)}">Opmaak gereed</button><a class="sp-teamwear-next" href="#klantpreview">Voorstel bekijken</a><a class="sp-teamwear-next" target="_blank" href="${base.replace(/\/workspace\/sportpaleis$/u, "")}/api/sportpaleis/v1/teamkit-proposals/${encodeURIComponent(proposal.id)}/pdf">PDF openen</a><a class="sp-teamwear-next" data-link href="${base}/voorstellen/${encodeURIComponent(proposal.id)}?mode=beheer#mail">Via Mail voorbereiden</a></aside></div>` : `<div class="sp-club-empty"><h3>Begin met een kledingstuk</h3><p>Kies visueel uit de centrale catalogus; vereniging is niet verplicht.</p><a class="sp-button sp-button--primary" href="#catalogus">Naar catalogus</a></div>`}</section>`;
}

function reviewPlacement(state: PilotBootstrap, proposal: TeamkitProposal, placement: TeamkitProposalPlacement, base: string): string {
  const [x, y] = visualPoint(placement); const asset = placement.productionAssetId ? state.productionElements.find(({ id }) => id === placement.productionAssetId) : undefined;
  const image = proposalSourcePreview(proposal, placement.sourceId, base) ?? (asset?.ownerType === "ASSOCIATION" ? associationLogo(state, proposal) : null);
  return `<span class="sp-review-placement sp-review-placement--${placement.kind.toLocaleLowerCase()}" data-visual-surface="${visualSurfaceForPreset(placement.preset)}" style="--review-x:${10 + (x * .8)}%;--review-y:${10 + (y * .83)}%;--review-width:${placement.widthPercent * .8}%;--placement-color:${esc(placement.colorOverride ?? "#ffffff")}">${image ? `<img src="${image}" alt="${esc(placement.label)}">` : `<b>${esc(placement.text ?? placement.label)}</b>`}</span>`;
}

function reviewGarment(state: PilotBootstrap, proposal: TeamkitProposal, item: TeamkitProposalItem, side: "FRONT" | "BACK", base: string): string {
  const placements = item.placements.filter((placement) => placement.side === side).map((placement) => reviewPlacement(state, proposal, placement, base)).join("");
  return `<figure class="sp-review-garment"><div><img src="${itemImage(state, item)}" alt="${esc(item.productName)} ${side === "FRONT" ? "voorzijde" : "achterzijde"}">${placements}</div><figcaption>${side === "FRONT" ? "Voorzijde" : "Achterzijde"}</figcaption></figure>`;
}

function customerReview(state: PilotBootstrap, proposal: TeamkitProposal, base: string): string {
  const latest = proposal.revisions.find(({ number }) => number === proposal.currentRevision); const feedback = proposal.feedback.filter(({ revision }) => revision === proposal.currentRevision);
  const garments = proposal.items.map((item) => { const price = item.catalogSnapshot; return `<article class="sp-review-item"><header><div><small>${esc(item.catalogSnapshot?.brand ?? "TEAMWEAR")} · ${esc(item.articleNumber ?? "Artikel volgt")}</small><h3>${esc(item.productName)}</h3></div><span>${esc(item.color)}</span></header><div class="sp-review-item__views">${reviewGarment(state, proposal, item, "FRONT", base)}${reviewGarment(state, proposal, item, "BACK", base)}</div>${price?.advicePriceEur != null ? `<footer><span>Adviesprijs ${euro(price.advicePriceEur)}</span><strong>${esc(price.priceLabel ?? "Teamprijs")} ${euro(price.effectivePriceEur)}</strong></footer>` : ""}</article>`; }).join("");
  return `<section class="sp-club-section sp-visual-review" id="klantpreview"><div class="sp-club-section__head"><div><p>KLANTREVIEW · V${proposal.currentRevision}</p><h2>Professioneel Teamwear-voorstel</h2><span>Collectie, front/back en prijscontext zonder interne assets, marges of productievelden.</span></div><span>${feedback.length} ${feedback.length === 1 ? "reactie" : "reacties"}</span></div><div class="sp-visual-review__frame"><header class="sp-review-hero"><div><p>SPORT 2000 SPORTPALEIS</p><h2>${esc(proposal.title)}</h2><span>${esc(proposal.association.name ?? proposal.customer.name)}${proposal.team ? ` · ${esc(proposal.team)}` : ""}</span></div><strong>${esc(proposal.proposalNumber)} · V${proposal.currentRevision}</strong></header><div class="sp-review-items">${garments || latest?.previewHtml || ""}</div><aside><div><p>Feedback bij deze versie</p><h3>${feedback[0] ? `“${esc(feedback[0].message)}”` : "Alles rustig bekijken"}</h3><span>Feedback blijft bij exact deze revision.</span></div><button class="sp-button sp-button--secondary" type="button" disabled>Feedback geven in beveiligde klantlink</button></aside><footer><div><strong>Exact voorstel ${esc(proposal.proposalNumber)} · V${proposal.currentRevision}</strong><span>Akkoord is een bewuste aparte actie; er start geen productie.</span></div><button class="sp-button sp-button--primary" type="button" disabled>${proposal.approval ? "Versie goedgekeurd" : "Voorstel akkoord"}</button></footer></div></section>`;
}

function teamwearEntry(state: PilotBootstrap, base: string): string {
  const relationships = buildTeamwearRelationships(state); const existing = relationships.filter(({ kind }) => ["ASSOCIATION", "ORGANIZATION", "TEAM"].includes(kind)).slice(0, 8);
  return `<section class="sp-teamwear-entry"><header><div><p>SPORTPALEIS WORKSPACE</p><h1>Teamwear Studio</h1></div><ol><li class="is-done">1 <span>Collectie</span></li><li class="is-active">2 <span>Visueel ontwerpen</span></li><li>3 <span>Maten & aantallen</span></li><li>4 <span>Voorstel & akkoord</span></li></ol></header><div class="sp-teamwear-start"><article class="is-active"><i>♧</i><div><h2>Nieuwe collectie samenstellen</h2><p>Start zonder vereniging vanuit Stanno, Nike, adidas, JAKO, Robey en toekomstige merken.</p></div><a href="#catalogus">Open catalogus →</a></article><article><i>◎</i><div><h2>Bestaande klant/team</h2><p>Zoek een bekende klant, club, team, bedrijf, school of organisatie.</p></div><button type="button" data-action="teamwear-toggle-contexts">Kies context →</button></article><article><i>▣</i><div><h2>Snelle Teamorder</h2><p>Ken je kleding en bedrukking al? Ga direct naar personen, maten en aantallen.</p></div><a data-link href="${base}/orders/team">Open Teamorder →</a></article></div><section class="sp-teamwear-context-picker" data-teamwear-contexts hidden><header><div><p>GEDEELDE RELATIONSHIP CONTEXT</p><h2>Kies bestaande context</h2></div><label><input type="search" data-teamwear-context-search placeholder="Naam, e-mail, telefoon of organisatie"></label></header><div>${existing.map((context) => `<button type="button" data-teamwear-context="${esc(context.searchableTerms.toLocaleLowerCase("nl-NL"))}"><span>${esc(initial(context.name))}</span><div><strong>${esc(context.name)}</strong><small>${esc(context.subtitle)}${context.email ? ` · ${esc(context.email)}` : ""}</small></div></button>`).join("")}</div></section></section>`;
}

export function teamkitProposalExperience(state: PilotBootstrap, proposalId: string, base: string): string {
  const proposal = state.teamkitProposals?.find(({ id }) => id === proposalId);
  if (!proposal) return `<section class="sp-empty"><h1>Voorstel niet gevonden</h1><a class="sp-button sp-button--primary" data-link href="${base}/voorstellen">Terug</a></section>`;
  return `<a class="sp-back" data-link href="${base}/voorstellen">← Voorstellen</a>${teamwearEntry(state, base)}${clubHome(state, proposal, base)}${studio(state, proposal, base)}${customerReview(state, proposal, base)}`;
}

function selectedPlacement(app: ParentNode): HTMLElement | null { return app.querySelector<HTMLElement>(".sp-studio-placement.is-selected"); }
function hiddenValue(placement: ParentNode, name: string): HTMLInputElement { return placement.querySelector<HTMLInputElement>(`[name="${name}"]`)!; }
function markStudioDirty(app: ParentNode): void { const state = app.querySelector<HTMLElement>("[data-studio-save-state]"); if (state) { state.textContent = "Niet-opgeslagen wijzigingen"; state.classList.add("is-dirty"); } }
function showPlacementProperties(app: ParentNode, placement: HTMLElement): void {
  app.querySelectorAll(".sp-studio-placement.is-selected").forEach((node) => node.classList.remove("is-selected")); placement.classList.add("is-selected");
  const panel = app.querySelector<HTMLElement>("[data-studio-properties]"); if (!panel) return; panel.querySelector<HTMLElement>(".sp-studio-properties__empty")!.hidden = true; panel.querySelector<HTMLElement>(".sp-studio-properties__selected")!.hidden = false;
  const set = (property: string, value: string) => { const input = panel.querySelector<HTMLInputElement | HTMLSelectElement>(`[data-property="${property}"]`); if (input) input.value = value; };
  set("label", hiddenValue(placement, "placementLabel").value); set("preset", hiddenValue(placement, "placementPreset").value); set("text", hiddenValue(placement, "placementText").value); set("color", hiddenValue(placement, "placementColor").value || "#ffffff"); set("width", hiddenValue(placement, "placementWidth").value); set("physicalWidth", hiddenValue(placement, "placementPhysicalWidthMm").value); set("physicalHeight", hiddenValue(placement, "placementPhysicalHeightMm").value); set("route", hiddenValue(placement, "placementRoute").value);
  const title = panel.querySelector<HTMLElement>("[data-property-title]"); if (title) title.textContent = hiddenValue(placement, "placementLabel").value; const output = panel.querySelector<HTMLOutputElement>('[data-property-output="width"]'); if (output) output.value = `${hiddenValue(placement, "placementWidth").value}%`;
  const textProperty = panel.querySelector<HTMLElement>("[data-text-property]"); if (textProperty) textProperty.hidden = ["CLUB_LOGO", "SPONSOR"].includes(hiddenValue(placement, "placementKind").value);
  const colorProperty = panel.querySelector<HTMLElement>("[data-color-property]"); if (colorProperty) { const supported = placement.dataset.recolorable === "true"; colorProperty.classList.toggle("is-disabled", !supported); colorProperty.querySelectorAll<HTMLInputElement | HTMLButtonElement>("input,button").forEach((control) => { control.disabled = !supported; }); }
  let quality = panel.querySelector<HTMLElement>("[data-asset-quality-warning]"); if (!quality) { quality = document.createElement("p"); quality.dataset.assetQualityWarning = ""; quality.className = "sp-studio-quality-warning"; panel.querySelector<HTMLElement>(".sp-studio-properties__selected header")?.insertAdjacentElement("afterend", quality); }
  const betterSource = ["LOW_RES_BETTER_SOURCE_REQUIRED", "UNKNOWN_REVIEW"].includes(placement.dataset.visualQuality ?? ""); quality.hidden = !betterSource; quality.textContent = betterSource ? "Betere of transparante bron aanbevolen. Het origineel blijft ongewijzigd bewaard." : "";
}
function applyPlacementProperty(app: ParentNode, property: string, value: string): void {
  const placement = selectedPlacement(app); if (!placement) return; const names: Record<string, string> = { label: "placementLabel", preset: "placementPreset", text: "placementText", color: "placementColor", width: "placementWidth", physicalWidth: "placementPhysicalWidthMm", physicalHeight: "placementPhysicalHeightMm", route: "placementRoute" }; const name = names[property]; if (!name) return; hiddenValue(placement, name).value = value;
  if (property === "label") { placement.setAttribute("aria-label", value); const title = app.querySelector<HTMLElement>("[data-property-title]"); if (title) title.textContent = value; }
  if (property === "text") { const text = placement.querySelector<HTMLElement>(".sp-studio-placement__body span"); if (text) text.textContent = value; }
  if (property === "width") { placement.style.setProperty("--placement-width", `${value}%`); const output = app.querySelector<HTMLOutputElement>('[data-property-output="width"]'); if (output) output.value = `${value}%`; }
  if (property === "color" && placement.dataset.recolorable === "true") { placement.dataset.colorOverride = value; placement.style.setProperty("--placement-color", value); }
  if (property === "preset") { const [x, y] = DEFAULT_POSITION[value] ?? [50, 50]; hiddenValue(placement, "placementVisualX").value = String(x); hiddenValue(placement, "placementVisualY").value = String(y); placement.style.setProperty("--placement-x", `${x}%`); placement.style.setProperty("--placement-y", `${y}%`); applyVisualSurface(placement, value); }
  markStudioDirty(app);
}

function newPlacementMarkup(input: { id: string; kind: TeamkitProposalPlacement["kind"]; label: string; side: "FRONT" | "BACK"; text?: string; sourceId?: string; assetId?: string; assetVersion?: string; image?: string | null; recolorable?: boolean; visualQuality?: string }): string {
  const preset = input.side === "BACK" ? "RUG_MIDDEN" : ["SPONSOR", "FREE_TEXT"].includes(input.kind) ? "MIDDENBORST" : "LINKERBORST"; const [x, y] = DEFAULT_POSITION[preset]; const width = input.kind === "BACK_NUMBER" ? 28 : input.kind === "SPONSOR" ? 34 : input.kind === "FREE_TEXT" ? 42 : 20; const display = input.image ? `<img src="${input.image}" alt="${esc(input.label)}" draggable="false">` : `<span>${esc(input.text ?? input.label)}</span>`;
  return `<article class="sp-studio-placement sp-studio-placement--${input.kind.toLocaleLowerCase()} is-selected" data-proposal-placement data-placement-id="${esc(input.id)}" data-placement-side="${input.side}" data-recolorable="${input.recolorable ?? !input.image}" data-visual-quality="${esc(input.visualQuality ?? (input.assetId ? "PRODUCTION_READY" : "TEXT"))}" style="--placement-x:${x}%;--placement-y:${y}%;--placement-width:${width}%;--placement-color:#ffffff"><input type="hidden" name="placementKind" value="${input.kind}"><input type="hidden" name="placementLabel" value="${esc(input.label)}"><input type="hidden" name="placementSide" value="${input.side}"><input type="hidden" name="placementPreset" value="${preset}"><input type="hidden" name="placementText" value="${esc(input.text ?? "")}"><input type="hidden" name="placementColor" value="#ffffff"><input type="hidden" name="placementWidth" value="${width}"><input type="hidden" name="placementVisualX" value="${x}"><input type="hidden" name="placementVisualY" value="${y}"><input type="hidden" name="placementSourceId" value="${esc(input.sourceId ?? "")}"><input type="hidden" name="placementAssetId" value="${esc(input.assetId ?? "")}"><input type="hidden" name="placementRoute" value="NOG_TE_BEPALEN"><input type="hidden" name="placementSupplier" value=""><input type="hidden" name="placementNote" value=""><input type="hidden" name="placementPhysicalWidthMm" value=""><input type="hidden" name="placementPhysicalHeightMm" value=""><button type="button" class="sp-studio-placement__body" aria-label="${esc(input.label)} selecteren">${display}</button><button type="button" class="sp-studio-resize" data-studio-resize aria-label="${esc(input.label)} schalen"></button></article>`;
}

export function activateTeamkitExperience(app: HTMLDivElement, state: PilotBootstrap): void {
  app.querySelectorAll<HTMLButtonElement>("[data-action='teamwear-toggle-contexts']").forEach((button) => button.addEventListener("click", () => { const picker = app.querySelector<HTMLElement>("[data-teamwear-contexts]"); if (picker) { picker.hidden = !picker.hidden; if (!picker.hidden) picker.querySelector<HTMLInputElement>("input")?.focus(); } }));
  app.querySelector<HTMLInputElement>("[data-teamwear-context-search]")?.addEventListener("input", (event) => { const value = (event.target as HTMLInputElement).value.toLocaleLowerCase("nl-NL"); app.querySelectorAll<HTMLElement>("[data-teamwear-context]").forEach((row) => { row.hidden = !String(row.dataset.teamwearContext).includes(value); }); });
  const studioWrap = app.querySelector<HTMLElement>(".sp-teamwear-studio-wrap");
  const workspaceShell = app.querySelector<HTMLElement>(".sp-workspace");
  const proposalId = studioWrap?.querySelector<HTMLElement>("[data-teamkit-studio]")?.dataset.proposalId;
  const proposal = state.teamkitProposals?.find(({ id }) => id === proposalId);
  const setFocusMode = (enabled: boolean) => {
    studioWrap?.classList.toggle("is-focus", enabled);
    workspaceShell?.classList.toggle("is-teamwear-focus", enabled);
    if (enabled) studioWrap?.scrollIntoView({ block: "start" });
  };
  app.querySelectorAll<HTMLAnchorElement>('a[href="#teamkit-studio"]').forEach((link) => link.addEventListener("click", () => setFocusMode(true)));
  app.querySelectorAll<HTMLAnchorElement>('a[href="#klantpreview"]').forEach((link) => link.addEventListener("click", () => setFocusMode(false)));
  if (studioWrap) {
    const exit = document.createElement("button");
    exit.type = "button"; exit.className = "sp-teamwear-focus-back"; exit.textContent = `← ${proposal?.association.name ?? proposal?.customer.name ?? "Teamwear"} / ${proposal?.season ?? "Collectie"}`;
    exit.addEventListener("click", () => setFocusMode(false));
    studioWrap.querySelector(".sp-teamwear-studio-head")?.prepend(exit);
  }
  if (location.hash === "#teamkit-studio") setFocusMode(true);
  const studio = app.querySelector<HTMLElement>("[data-teamkit-studio]");
  studio?.querySelectorAll<HTMLElement>("[data-print-area]").forEach((area) => { area.dataset.garmentSurfaceMap = "GARMENT_SURFACE_V1"; });
  studio?.querySelectorAll<HTMLElement>("[data-proposal-placement]").forEach((placement) => { const sourceId = hiddenValue(placement, "placementSourceId").value; const assetId = hiddenValue(placement, "placementAssetId").value; placement.dataset.visualQuality = proposal?.sources.find(({ id }) => id === sourceId)?.quality.status ?? (assetId ? "PRODUCTION_READY" : "TEXT"); applyVisualSurface(placement, hiddenValue(placement, "placementPreset").value); });
  if (!studio || studio.dataset.editable !== "true" || !proposal) return;
  const editor = studio.querySelector<HTMLFormElement>("[data-teamkit-editor-form]")!; const history: string[] = [editor.innerHTML]; let historyIndex = 0;
  const remember = () => { const snapshot = editor.innerHTML; if (history[historyIndex] === snapshot) return; history.splice(historyIndex + 1); history.push(snapshot); if (history.length > 30) history.shift(); historyIndex = history.length - 1; };
  const restore = (index: number) => { if (index < 0 || index >= history.length) return; historyIndex = index; editor.innerHTML = history[historyIndex]; markStudioDirty(studio); };
  const placeAt = (placement: HTMLElement, x: number, y: number) => { const constrained = constrainPlacementToSurface(placement, x, y); hiddenValue(placement, "placementVisualX").value = constrained.x.toFixed(2); hiddenValue(placement, "placementVisualY").value = constrained.y.toFixed(2); hiddenValue(placement, "placementWidth").value = constrained.width.toFixed(1); placement.style.setProperty("--placement-x", `${constrained.x}%`); placement.style.setProperty("--placement-y", `${constrained.y}%`); placement.style.setProperty("--placement-width", `${constrained.width}%`); };
  studio.addEventListener("click", (event) => {
    const target = event.target as HTMLElement; const placement = target.closest<HTMLElement>("[data-proposal-placement]"); if (placement) { showPlacementProperties(studio, placement); return; }
    const button = target.closest<HTMLButtonElement>("button[data-action]"); if (!button) return;
    if (button.dataset.action === "studio-side") { const item = button.closest<HTMLElement>("[data-proposal-item]"); if (!item) return; item.querySelectorAll<HTMLButtonElement>("[data-action='studio-side']").forEach((candidate) => candidate.classList.toggle("is-active", candidate === button)); item.querySelectorAll<HTMLElement>("[data-studio-view]").forEach((view) => { view.hidden = view.dataset.studioView !== button.dataset.side; }); return; }
    if (button.dataset.action === "studio-select-item") { const id = button.dataset.itemId; studio.querySelectorAll<HTMLElement>("[data-proposal-item]").forEach((item) => { item.hidden = item.dataset.itemId !== id; }); studio.querySelectorAll<HTMLButtonElement>("[data-action='studio-select-item']").forEach((candidate) => candidate.classList.toggle("is-active", candidate.dataset.itemId === id)); return; }
    if (button.dataset.action === "studio-undo") { restore(historyIndex - 1); return; }
    if (button.dataset.action === "studio-redo") { restore(historyIndex + 1); return; }
    if (button.dataset.action === "studio-color") { applyPlacementProperty(studio, "color", button.dataset.color ?? "#ffffff"); remember(); return; }
    if (["studio-align-x", "studio-align-y", "studio-reset", "studio-layer-front", "studio-layer-back", "studio-duplicate", "studio-remove-placement"].includes(button.dataset.action ?? "")) {
      const selected = selectedPlacement(studio); if (!selected) return;
      if (button.dataset.action === "studio-align-x") placeAt(selected, 50, Number(hiddenValue(selected, "placementVisualY").value));
      if (button.dataset.action === "studio-align-y") placeAt(selected, Number(hiddenValue(selected, "placementVisualX").value), 50);
      if (button.dataset.action === "studio-reset") { const [x, y] = DEFAULT_POSITION[hiddenValue(selected, "placementPreset").value] ?? [50, 50]; placeAt(selected, x, y); }
      if (button.dataset.action === "studio-layer-front") selected.parentElement?.append(selected);
      if (button.dataset.action === "studio-layer-back") selected.parentElement?.prepend(selected);
      if (button.dataset.action === "studio-duplicate") { const copy = selected.cloneNode(true) as HTMLElement; copy.dataset.placementId = clientPlacementId(); copy.querySelectorAll(".is-selected").forEach((node) => node.classList.remove("is-selected")); selected.insertAdjacentElement("afterend", copy); const x = Math.min(90, Number(hiddenValue(copy, "placementVisualX").value) + 4); const y = Math.min(90, Number(hiddenValue(copy, "placementVisualY").value) + 4); placeAt(copy, x, y); showPlacementProperties(studio, copy); }
      if (button.dataset.action === "studio-remove-placement") { selected.remove(); studio.querySelector<HTMLElement>(".sp-studio-properties__selected")!.hidden = true; studio.querySelector<HTMLElement>(".sp-studio-properties__empty")!.hidden = false; }
      markStudioDirty(studio); remember(); return;
    }
  });
  studio.addEventListener("input", (event) => { const input = (event.target as HTMLElement).closest<HTMLInputElement | HTMLSelectElement>("[data-property]"); if (input) applyPlacementProperty(studio, input.dataset.property!, input.value); });
  studio.addEventListener("change", (event) => { if ((event.target as HTMLElement).closest("[data-property]")) remember(); });
  studio.addEventListener("pointerdown", (event) => {
    const handle = (event.target as HTMLElement).closest<HTMLElement>("[data-studio-resize]"); const placement = (event.target as HTMLElement).closest<HTMLElement>("[data-proposal-placement]"); if (!placement) return; const area = placement.closest<HTMLElement>("[data-print-area]"); if (!area) return; const placementRect = placement.getBoundingClientRect(); const resizing = Boolean(handle) || (event.clientX >= placementRect.right - 28 && event.clientY >= placementRect.bottom - 28); event.preventDefault(); showPlacementProperties(studio, placement); placement.setPointerCapture(event.pointerId);
    const rect = area.getBoundingClientRect(); const startX = event.clientX; const startY = event.clientY; const originX = Number(hiddenValue(placement, "placementVisualX").value); const originY = Number(hiddenValue(placement, "placementVisualY").value); const originWidth = Number(hiddenValue(placement, "placementWidth").value);
    const move = (moveEvent: PointerEvent) => { if (moveEvent.pointerId !== event.pointerId) return; if (resizing) { const requestedWidth = originWidth + ((moveEvent.clientX - startX) / rect.width) * 100; const constrained = constrainPlacementToSurface(placement, originX, originY, requestedWidth); hiddenValue(placement, "placementWidth").value = constrained.width.toFixed(1); placement.style.setProperty("--placement-width", `${constrained.width}%`); const output = studio.querySelector<HTMLOutputElement>('[data-property-output="width"]'); const slider = studio.querySelector<HTMLInputElement>('[data-property="width"]'); if (output) output.value = `${Math.round(constrained.width)}%`; if (slider) slider.value = String(Math.round(constrained.width)); } else { let x = originX + ((moveEvent.clientX - startX) / rect.width) * 100; let y = originY + ((moveEvent.clientY - startY) / rect.height) * 100; const surface = placement.dataset.visualSurface; const guideX = !surface?.includes("SLEEVE") && Math.abs(x - 50) < 2.5; const guideY = Math.abs(y - 50) < 2.5; if (guideX) x = 50; if (guideY) y = 50; area.classList.toggle("has-guide-x", guideX); area.classList.toggle("has-guide-y", guideY); placeAt(placement, x, y); } markStudioDirty(studio); };
    const up = (upEvent: PointerEvent) => { if (upEvent.pointerId !== event.pointerId) return; area.classList.remove("has-guide-x", "has-guide-y"); placement.removeEventListener("pointermove", move); placement.removeEventListener("pointerup", up); placement.removeEventListener("pointercancel", up); remember(); };
    placement.addEventListener("pointermove", move); placement.addEventListener("pointerup", up); placement.addEventListener("pointercancel", up);
  });
  const addPlacement = (input: Parameters<typeof newPlacementMarkup>[0]) => { const item = studio.querySelector<HTMLElement>("[data-proposal-item]:not([hidden])"); const side = item?.querySelector<HTMLButtonElement>("[data-action='studio-side'].is-active")?.dataset.side as "FRONT" | "BACK" | undefined; const area = item?.querySelector<HTMLElement>(`[data-print-area="${side ?? "FRONT"}"]`); if (!area) return; studio.querySelectorAll(".sp-studio-placement.is-selected").forEach((node) => node.classList.remove("is-selected")); area.insertAdjacentHTML("beforeend", newPlacementMarkup({ ...input, side: side ?? "FRONT" })); const added = area.querySelector<HTMLElement>("[data-proposal-placement]:last-child"); if (added) { added.dataset.visualQuality = input.visualQuality ?? (input.assetId ? "PRODUCTION_READY" : "TEXT"); if (input.kind === "FREE_TEXT" && (side ?? "FRONT") === "FRONT") placeAt(added, 50, 68); applyVisualSurface(added, hiddenValue(added, "placementPreset").value); showPlacementProperties(studio, added); } markStudioDirty(studio); remember(); };
  studio.querySelectorAll<HTMLButtonElement>("[data-action='studio-add-asset']").forEach((button) => button.addEventListener("click", () => addPlacement({ id: clientPlacementId(), kind: button.dataset.assetKind as TeamkitProposalPlacement["kind"], label: button.dataset.assetLabel ?? "Clublogo", side: "FRONT", assetId: button.dataset.assetId, assetVersion: button.dataset.assetVersion, image: button.querySelector<HTMLImageElement>("img")?.src ?? associationLogo(state, proposal), recolorable: button.dataset.assetRecolorable === "true" })));
  studio.querySelectorAll<HTMLButtonElement>("[data-action='studio-add-source']").forEach((button) => button.addEventListener("click", () => addPlacement({ id: clientPlacementId(), kind: button.dataset.assetKind as TeamkitProposalPlacement["kind"], label: button.dataset.assetLabel ?? "Sponsor", side: "FRONT", sourceId: button.dataset.sourceId, image: button.querySelector<HTMLImageElement>("img")?.src ?? null, recolorable: button.dataset.assetRecolorable === "true", visualQuality: button.dataset.assetQuality })));
  studio.querySelectorAll<HTMLButtonElement>("[data-action='studio-add-text']").forEach((button) => button.addEventListener("click", () => addPlacement({ id: clientPlacementId(), kind: button.dataset.kind as TeamkitProposalPlacement["kind"], label: button.dataset.kind === "BACK_NUMBER" ? "Rugnummer" : button.dataset.kind === "FREE_TEXT" ? "Vrije opdruk" : "Initialen", side: "FRONT", text: button.dataset.text })));
  app.querySelector<HTMLButtonElement>(".sp-teamwear-studio-head [data-action='studio-undo']")?.addEventListener("click", () => restore(historyIndex - 1));
  app.querySelector<HTMLButtonElement>(".sp-teamwear-studio-head [data-action='studio-redo']")?.addEventListener("click", () => restore(historyIndex + 1));
  studio.addEventListener("keydown", (event) => { if (!(event.ctrlKey || event.metaKey)) return; if (event.key.toLocaleLowerCase() === "z") { event.preventDefault(); restore(historyIndex + (event.shiftKey ? 1 : -1)); } if (event.key.toLocaleLowerCase() === "d") { event.preventDefault(); studio.querySelector<HTMLButtonElement>("[data-action='studio-duplicate']")?.click(); } });
}
